def verify(ctx):
    """验收 result.json 交付件：检查 delivered 字段值为固定字符串"actual file bytes"。"""
    import json

    # 获取实际文件列表
    files = ctx.files
    if not files:
        return {"status": "fail", "checks": [{"name": "文件存在性", "status": "fail", "reason": "未找到任何交付文件"}]}

    # 查找 result.json
    result_file = None
    for f in files:
        if f.get("name") == "result.json":
            result_file = f
            break

    if not result_file:
        return {"status": "fail", "checks": [{"name": "文件存在性", "status": "fail", "reason": "未找到 result.json 文件"}]}

    # 读取文件内容
    content = ctx.read("result.json")
    if not content:
        return {"status": "fail", "checks": [{"name": "文件可读性", "status": "fail", "reason": "无法读取 result.json 内容"}]}

    # 解析 JSON
    try:
        data = json.loads(content)
    except json.JSONDecodeError as e:
        return {"status": "fail", "checks": [{"name": "JSON 格式", "status": "fail", "reason": f"JSON 解析失败：{str(e)}"}]}

    # 检查 delivered 字段
    if "delivered" not in data:
        return {"status": "fail", "checks": [{"name": "delivered 字段存在性", "status": "fail", "reason": "缺少 delivered 字段"}]}

    if data["delivered"] != "actual file bytes":
        return {"status": "fail", "checks": [{"name": "delivered 字段值", "status": "fail", "reason": f"delivered 字段值应为 'actual file bytes'，实际为 '{data['delivered']}'"}]}

    return {"status": "pass", "checks": [{"name": "交付件验证", "status": "pass", "reason": "result.json 内容符合预期"}]}
